-- Rebuild canonical exercises table from bundled lottie catalog.
-- This intentionally removes old exercise rows and re-seeds all exercises.

begin;

alter table if exists public.template_exercises
  drop constraint if exists template_exercises_exercise_id_fkey;
alter table if exists public.session_exercises
  drop constraint if exists session_exercises_exercise_id_fkey;
alter table if exists public.exercise_alternatives
  drop constraint if exists exercise_alternatives_alternative_exercise_id_fkey;

drop table if exists public.exercises;

create table public.exercises (
  id text not null,
  name text not null,
  type text null,
  lottie_path text not null,
  created_at timestamp with time zone null default now(),
  constraint exercises_pkey primary key (id)
) tablespace pg_default;

on conflict (id) do update
set
  name = excluded.name,
  type = excluded.type,
  lottie_path = excluded.lottie_path;

-- Aggressive cleanup for fresh-project reset:
-- remove malformed/orphaned rows with missing ids before rebuilding FK integrity.
delete from public.exercise_alternatives
where alternative_exercise_id is null
   or btrim(alternative_exercise_id) = '';

delete from public.session_exercises
where exercise_id is null
   or btrim(exercise_id) = '';

delete from public.template_exercises
where exercise_id is null
   or btrim(exercise_id) = '';

-- Remove child rows whose parent rows are missing.
delete from public.session_sets ss
where not exists (
  select 1
  from public.session_exercises se
  where se.id = ss.session_exercise_id
);

delete from public.template_sets ts
where not exists (
  select 1
  from public.template_exercises te
  where te.id = ts.template_exercise_id
);

delete from public.exercise_alternatives ea
where not exists (
  select 1
  from public.template_exercises te
  where te.id = ea.template_exercise_id
);

-- Preserve any already-referenced exercise ids that are not in lottie catalog.
-- These are inserted as fallback rows so FK integrity is maintained.
select
  refs.id,
  refs.id,
  'WR',
  '',
  now()
from (
  select exercise_id as id from public.template_exercises
  union
  select exercise_id as id from public.session_exercises
  union
  select alternative_exercise_id as id from public.exercise_alternatives
) refs
left join public.exercises e
  on e.id = refs.id
where refs.id is not null
  and refs.id <> ''
  and e.id is null
on conflict (id) do nothing;

-- Ensure all referenced exercise ids still exist after rebuild.
do $$
declare
  missing_count int;
begin
  select count(*) into missing_count
  from (
    select exercise_id as id from public.template_exercises
    union
    select exercise_id as id from public.session_exercises
    union
    select alternative_exercise_id as id from public.exercise_alternatives
  ) refs
  left join public.exercises e on e.id = refs.id
  where refs.id is not null
    and refs.id <> ''
    and e.id is null;

  if missing_count > 0 then
    raise exception 'Exercises rebuild failed: % referenced exercise ids are missing after reseed', missing_count;
  end if;
end $$;

alter table public.template_exercises
  add constraint template_exercises_exercise_id_fkey
  foreign key (exercise_id) references public.exercises(id);

alter table public.session_exercises
  add constraint session_exercises_exercise_id_fkey
  foreign key (exercise_id) references public.exercises(id);

alter table public.exercise_alternatives
  add constraint exercise_alternatives_alternative_exercise_id_fkey
  foreign key (alternative_exercise_id) references public.exercises(id);

commit;
